let isSidebarClosed = false;

// ذاكرة تخزين مؤقت لتسريع تسوية النصوص والبحث
const normCache = new Map();
const prefixCache = new Map();

function showToast(msg) {
    const toast = document.getElementById('toast');
    const toastMsg = document.getElementById('toastMsg');
    if (toast && toastMsg) {
        toastMsg.textContent = msg;
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2000);
    }
}

function toggleDropdown(id) {
    const el = document.getElementById(id);
    if (el) el.classList.toggle('hidden');
}

// فتح وإغلاق لوحة الإدخال الجانبية
function toggleSidebarInPlace() {
    const body = document.body;
    const reopenBtn = document.getElementById('reopenSidebarBtn');
    isSidebarClosed = !isSidebarClosed;

    if (isSidebarClosed) {
        body.classList.add('sidebar-is-closed');
        if (reopenBtn) {
            reopenBtn.classList.remove('hidden');
            reopenBtn.classList.add('flex');
        }
    } else {
        body.classList.remove('sidebar-is-closed');
        if (reopenBtn) {
            reopenBtn.classList.add('hidden');
            reopenBtn.classList.remove('flex');
        }
    }
}

// التبديل السريع للشاشات الصغيرة
function setMobileView(view) {
    const sidebar = document.getElementById('sidebarCol');
    const results = document.getElementById('resultsCol');
    const btnInput = document.getElementById('btn-show-input');
    const btnResults = document.getElementById('btn-show-results');

    if (window.innerWidth >= 1024) return;

    if (view === 'input') {
        if (sidebar) sidebar.style.display = 'flex';
        if (results) results.style.display = 'none';
        if (btnInput) btnInput.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn text-white flex items-center justify-center gap-1 shadow-xs";
        if (btnResults) btnResults.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn-sec flex items-center justify-center gap-1";
    } else {
        if (sidebar) sidebar.style.display = 'none';
        if (results) results.style.display = 'flex';
        if (btnInput) btnInput.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn-sec flex items-center justify-center gap-1";
        if (btnResults) btnResults.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn text-white flex items-center justify-center gap-1 shadow-xs";
    }
}

function triggerMobileResults() {
    if (window.innerWidth < 1024) {
        setMobileView('results');
    }
}

function openDataModal(tabMode = 'paste') {
    const modal = document.getElementById('dataInputModal');
    if (modal) {
        modal.classList.remove('hidden');
        switchModalTab(tabMode);
    }
}

function closeDataModal() {
    const modal = document.getElementById('dataInputModal');
    if (modal) modal.classList.add('hidden');
}

function handleModalBackdropClick(e) {
    if (e.target.id === 'dataInputModal') closeDataModal();
}

function switchModalTab(mode) {
    const uploadSec = document.getElementById('modalUploadSection');
    const pasteSec = document.getElementById('modalPasteSection');
    const uploadBtn = document.getElementById('modal-tab-upload-btn');
    const pasteBtn = document.getElementById('modal-tab-paste-btn');

    if (mode === 'upload') {
        uploadSec?.classList.remove('hidden');
        pasteSec?.classList.add('hidden');
        if (uploadBtn) uploadBtn.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn text-white flex items-center justify-center gap-1 shadow-xs";
        if (pasteBtn) pasteBtn.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn-sec flex items-center justify-center gap-1";
    } else {
        uploadSec?.classList.add('hidden');
        pasteSec?.classList.remove('hidden');
        if (uploadBtn) uploadBtn.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn-sec flex items-center justify-center gap-1";
        if (pasteBtn) pasteBtn.className = "flex-1 py-1.5 px-2.5 rounded-xl text-xs font-bold transition clay-btn text-white flex items-center justify-center gap-1 shadow-xs";
        
        requestAnimationFrame(() => {
            document.getElementById('namesInput')?.focus();
        });
    }
}

function saveModalAndDetect() {
    closeDataModal();
    processNames();
    showToast(translations[currentLang].modal_save_detect);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeDataModal();
});

function selectLang(lang) {
    if (currentLang === lang) {
        toggleDropdown('langMenu');
        return;
    }
    currentLang = lang;
    localStorage.setItem('siblings_lang', lang);
    const labelEl = document.getElementById('currentLangLabel');
    if (labelEl) {
        labelEl.textContent = {
            'ku_ba': 'بادینی',
            'ku_so': 'سۆرانی',
            'ar': 'العربية',
            'en': 'English'
        }[lang];
    }
    toggleDropdown('langMenu');
    changeLanguage(lang);
}

